// Turns all new articles into ONE digest message (Slack mrkdwn + HTML for e-mail).
const MAX_PER_QUERY = 10;
const articles = $input.all().map(i => i.json);
if (articles.length === 0) return []; // nothing new -> no message

const groups = {};
for (const a of articles) {
  const key = String(a.query || a.topic || 'Other').replace(/"/g, '');
  (groups[key] = groups[key] || []).push(a);
}

const day = $now.toFormat('yyyy-MM-dd');
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\|/g, '-').trim();
let text = `*News digest ${day}*: ${articles.length} new article(s)\n`;
let html = `<h2>News digest ${day}</h2>`;

for (const [query, list] of Object.entries(groups)) {
  list.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)));
  text += `\n*${esc(query)}* (${list.length})\n`;
  html += `<h3>${esc(query)} (${list.length})</h3><ul>`;
  for (const a of list.slice(0, MAX_PER_QUERY)) {
    text += `- <${a.url}|${esc(a.title)}> (${esc(a.source)})\n`;
    html += `<li><a href="${a.url}">${esc(a.title)}</a> (${esc(a.source)})</li>`;
  }
  if (list.length > MAX_PER_QUERY) text += `...and ${list.length - MAX_PER_QUERY} more\n`;
  html += '</ul>';
}

return [{ json: { text, html, count: articles.length,
  subject: `News digest ${day}: ${articles.length} new article(s)` } }];
